WITH unpacked AS (SELECT id, context['region'] AS region, SHIFTRIGHT(status_code, 2) AS status_code_high, COALESCE(context['trace'], 'direct') AS trace_or_default, CAST((status_code & 1) != 0 AS INT) AS is_flagged, context['trace'] AS trace FROM app_logs) SELECT CASE WHEN is_flagged >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_flagged_tier, COUNT(*) AS row_count, COUNT(*) AS row_count_2, SUM(status_code_high) AS total_status_code_high FROM unpacked GROUP BY 1
